	@Test
	void retainedProbeReportsOnlyWorkFromItsCurrentOpen() throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), new LmdbStoreConfig("spoc")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(false));
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			var values = repository.getValueFactory();
			var subject = values.createIRI("urn:subject:one");
			var predicate = values.createIRI("urn:predicate");
			var matchingObject = values.createLiteral("matching");
			var filteredObject = values.createLiteral("filtered");
			var firstContext = values.createIRI("urn:graph:first");
			var secondContext = values.createIRI("urn:graph:second");
			try (var connection = repository.getConnection()) {
				connection.begin();
				connection.add(subject, predicate, matchingObject, firstContext);
				connection.add(values.createIRI("urn:subject:two"), predicate, filteredObject, firstContext);
				connection.add(values.createIRI("urn:subject:three"), predicate, filteredObject, secondContext);
				connection.commit();
			}

			try (var dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
				NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
				long subjectId = source.idOf(subject);
				long predicateId = source.idOf(predicate);
				long matchingObjectId = source.idOf(matchingObject);
				long firstContextId = source.idOf(firstContext);
				long secondContextId = source.idOf(secondContext);
				assertThat(subjectId).isPositive();
				assertThat(predicateId).isPositive();
				assertThat(matchingObjectId).isPositive();
				assertThat(firstContextId).isPositive();
				assertThat(secondContextId).isPositive();

				try (NativeLmdbQuerySource.NativeProbe reused = source.newProbe()) {
					MeasurementObserver partialObserver = new MeasurementObserver();
					try (RecordIterator partial = reused.open(-1L, -1L, -1L, -1L, partialObserver)) {
						assertThat(partial.next()).isNotNull();
					}
					assertThat(partialObserver.onlyMeasurement().censored()).isTrue();

					MeasurementObserver exactObserver = new MeasurementObserver();
					try (RecordIterator exact = reused.open(subjectId, predicateId, matchingObjectId, firstContextId,
							exactObserver)) {
						assertThat(exact.next()).isNotNull();
						assertThat(exact.next()).isNull();
					}
					Measurement exactReused = exactObserver.onlyMeasurement();
					Measurement exactIndependent = independentlyMeasure(source, subjectId, predicateId,
							matchingObjectId, firstContextId);
					assertThat(exactReused).isEqualTo(exactIndependent);

					MeasurementObserver missingObserver = new MeasurementObserver();
					try (RecordIterator missing = reused.open(subjectId, predicateId, matchingObjectId, secondContextId,
							missingObserver)) {
						assertThat(missing.next()).isNull();
					}
					Measurement missingReused = missingObserver.onlyMeasurement();
					Measurement missingIndependent = independentlyMeasure(source, subjectId, predicateId,
							matchingObjectId, secondContextId);
					assertThat(missingReused).isEqualTo(missingIndependent);

					MeasurementObserver filteredObserver = new MeasurementObserver();
					try (RecordIterator filtered = reused.open(-1L, -1L, matchingObjectId, -1L, filteredObserver)) {
						assertThat(filtered.next()).isNotNull();
						assertThat(filtered.next()).isNull();
					}
					Measurement filteredReused = filteredObserver.onlyMeasurement();
					Measurement filteredIndependent = independentlyMeasure(source, -1L, -1L, matchingObjectId, -1L);
					assertThat(filteredReused).isEqualTo(filteredIndependent);
					assertThat(filteredReused.filtered()).isPositive();
				}
			}
		} finally {
			repository.shutDown();
		}
	}

	private static Measurement independentlyMeasure(NativeLmdbQuerySource source, long subject, long predicate,
			long object, long context) throws Exception {
		MeasurementObserver observer = new MeasurementObserver();
		try (RecordIterator rows = source.statements(subject, predicate, object, context, observer)) {
			while (rows.next() != null) {
				// Exhaust the independent cursor so both measurements cover the same scan.
			}
		}
		return observer.onlyMeasurement();
	}

	private record Measurement(boolean adjacency, long scanned, long matched, long filtered, boolean censored) {
	}

	private static final class MeasurementObserver implements NativeLmdbQuerySource.AdjacencyAccessObserver {
		private final List<Measurement> measurements = new ArrayList<>();

		@Override
		public void access(boolean used, String reason, StatementOrder requestedOrder, long subject, long predicate,
				long object, long context) {
		}

		@Override
		public void measurement(boolean adjacency, long scanned, long matched, long filtered, boolean censored) {
			measurements.add(new Measurement(adjacency, scanned, matched, filtered, censored));
		}

		Measurement onlyMeasurement() {
			assertThat(measurements).hasSize(1);
			return measurements.get(0);
		}
	}
